- আপনার রব তিনি ভাল জানেন কে তাঁর পথ থেকে বিচ্যুত হয়েছে, এবং তিনি ভাল জানেন। (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
- তোমাদেরকে গায়ব ও শাহাদতের জ্ঞানীর কাছে ফিরিয়ে আনা হবে এবং তিনি তোমাদেরকে যা করতে তা জানাবেন। (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- তোমাদের পুত্রদের হত্যা করে এবং তোমাদের নারীদের জীবিত রাখে, আর এতে তোমাদের রবের পক্ষ থেকে বড় পরীক্ষা রয়েছে। (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- নিশ্চয়ই আপনার রব তিনি ভাল জানেন কে তাঁর পথ থেকে বিচ্যুত হয়, এবং তিনি। (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- আল্লাহ, যাঁর জন্য আসমানসমূহে যা আছে ও জমিনে যা আছে। (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- তোমাদের পূর্ববর্তী সম্প্রদায়সমূহের মধ্যে, জিন ও মানুষের। (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- আল্লাহর ইবাদত কর, তাঁর বাইরে তোমাদের কোনো ইলাহ নেই, তোমরা কি ভয় কর না? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- আর আমরা তাদের অন্তরে আড়াল দিয়েছি যাতে তারা এটি বুঝতে না পারে, এবং তাদের কানে বধিরতা। (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- তিনি তাদের মধ্যে কিয়ামতের দিন সেই বিষয়ে ফয়সালা করবেন যা নিয়ে তারা মতবিরোধ করত। (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- তিনি বললেন: "হে আমার সম্প্রদায়! তোমরা দেখো, যদি আমি আমার রবের পক্ষ থেকে সুস্পষ্ট প্রমাণের ওপর থাকি।" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- এটি তোমাদের হাত যা অগ্রে পাঠিয়েছে তার কারণে, এবং আল্লাহ বান্দাদের প্রতি জালুমকারী নন। (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- তাদের জন্য দুনিয়াতে লাঞ্ছনা এবং আখিরাতে মহান শাস্তি রয়েছে। (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- আসমানসমূহে যা আছে ও জমিনে যা আছে, এবং আল্লাহ অভিভাবক হিসেবে যথেষ্ট। (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- তবে যারা ঈমান এনেছে ও সৎকর্ম করেছে, তাদের জন্য অফুরন্ত পুরস্কার রয়েছে। (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- তুমি আমার সাথে সেই বিষয়কে শরীক করো যার সম্পর্কে তোমার কোনো জ্ঞান নেই, তাদের আনুগত্য করো না। (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- নিশ্চয় এটি একটি স্মারক, তাই যারা ইচ্ছা করে তারা নিজ রবের পথ গ্রহণ করুক। (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- আর যে কৃতজ্ঞ হয়, সে নিজের জন্যই কৃতজ্ঞ হয়, আর যে অকৃতজ্ঞ হয়, তবে। (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- যারা সালাত কায়েম করে এবং যাকাত দেয় এবং আখিরাতের প্রতি দৃঢ় বিশ্বাস রাখে। (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- ইব্রাহীম, ইসমাঈল, ইসহাক, ইয়াকুব ও বংশধরদের প্রতি, এবং মূসা ও ঈসাকে যা দেওয়া হয়েছিল। (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- দলে দলে, যখন তারা সেখানে আসবে, তখন তার দরজাগুলো খুলে দেওয়া হবে এবং তার রক্ষকরা তাদের বলবে। (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- আল্লাহ তোমাদেরকে তোমাদের শপথের অসার কথার জন্য পাকড়াও করেন না, কিন্তু তিনি পাকড়াও করেন তার জন্য। (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- রহমত, তারা তাতে আনন্দিত হয়, আর যদি তারা নিজ হাতে যা করেছে তার জন্য কোনো অকল্যাণ আসে। (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- যার নিচে নদী প্রবাহিত, সেখানে তারা চিরস্থায়ী হবে, এবং কর্মীদের পুরস্কার কতই না উত্তম! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- আল্লাহ তিনি জানেন আসমানসমূহে যা আছে ও জমিনে যা আছে, এবং আল্লাহ। (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- আল্লাহর আনুগত্য কর এবং রাসূলের আনুগত্য কর; যদি তোমরা মুখ ফিরিয়ে নাও, তবে তার ওপর। (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- তাদের জন্য তাদের রবের কাছে তাদের পুরস্কার রয়েছে, তাদের কোনো ভয় নেই এবং তারা। (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- আর তারা বলল: "আমরা অস্থি ও ধূলিকণা হয়ে গেলেও কি নতুন সৃষ্টি হিসেবে পুনরুত্থিত হব?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- আর তারা আল্লাহ ছাড়া নিজেদের জন্য কোনো অভিভাবক ও সাহায্যকারী পায় না। (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "কতক্ষণ তুমি অবস্থান করলে?" তিনি বললেন: "আমি একদিন বা একদিনের কিছু অংশ অবস্থান করলাম।" তিনি বললেন। (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- কিয়ামতের দিন পর্যন্ত চিরস্থায়ী, আল্লাহ ছাড়া কোন ইলাহ আছে যে তোমাদের কাছে আসবে? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- যে সৎকর্ম করে, পুরুষ বা নারী, এবং সে মুমিন হয়। (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- যারা আল্লাহর পথ থেকে বাধা দেয় এবং তা বাঁকা করতে চায়, এবং তারা আখিরাতকে। (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- যেখানে ইচ্ছা খাও, কিন্তু এই গাছের কাছে যেও না, তাহলে তোমরা জালিম হবে। (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- বল: "হে আমার সম্প্রদায়! তোমরা নিজ অবস্থানে কাজ কর, আমিও কাজ করছি, শীঘ্রই তোমরা জানতে পারবে।" (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- নিশ্চয় ক্ষতিগ্রস্তরা তারাই যারা কিয়ামতের দিন নিজেদের ও নিজ পরিবারকে ক্ষতি করেছে, সাবধান। (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- যে নিজের জন্য হিদায়াত পায়, আর যে পথভ্রষ্ট হয়, সে নিজের জন্যই পথভ্রষ্ট হয়, এবং। (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- আর যারা কুফরী করে তারা বলে: "তার কাছে তার রবের পক্ষ থেকে কোনো নিদর্শন কেন নাজিল করা হলো না?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- যিনি তোমাদের জন্য রাত সৃষ্টি করেছেন যাতে তোমরা তাতে বিশ্রাম নাও এবং দিন দর্শনীয় হিসেবে, নিশ্চয়। (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
