- যখন তিনি কোনো কাজের সিদ্ধান্ত নেন, তখন তিনি তাকে বলেন: "হও"। (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- তোমরা জাহান্নামের দ্বারসমূহে প্রবেশ কর, সেখানে চিরস্থায়ী হয়ে থাক; অহংকারীদের আবাসস্থল কত নিকৃষ্ট! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- তুমি কি তাদের দেখনি, যাদেরকে কিতাবের অংশ দেওয়া হয়েছিল? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- তাদের জন্য জান্নাত রয়েছে, যার নিচে নদী প্রবাহিত, সেখানে তারা চিরস্থায়ী হবে। (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- হে আমার সম্প্রদায়, তোমরা নিজেদের অবস্থান অনুযায়ী কাজ কর, আমিও কাজ করছি; শীঘ্রই তোমরা জানতে পারবে। (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- যে আল্লাহ ও তাঁর রাসূলের বিরোধিতা করে, তার জন্য জাহান্নামের আগুন রয়েছে, সেখানে সে চিরস্থায়ী হবে। (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- তাদের অন্তরে আবরণ দিয়েছি, যাতে তারা তা না বোঝে, এবং তাদের কানে বধিরতা। (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- কোনো জনপদে সতর্ককারী পাঠালে, তার বিত্তশালী লোকেরা বলে: আমরা। (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- তারা বলল: আমাদের জন্য তোমার রবের কাছে দোয়া কর, যেন তিনি আমাদের কাছে স্পষ্ট করেন যে তা কী। (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- তারা অবশ্যই বলবে: আল্লাহ। বল: সমস্ত প্রশংসা আল্লাহর, কিন্তু তাদের অধিকাংশ। (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- তার সম্প্রদায়ের উত্তর শুধু এই ছিল যে, তারা বলল: তাদেরকে বহিষ্কার কর। (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- যার নিচে নদী প্রবাহিত, সেখানে তারা চিরকাল থাকবে; এটাই মহাসাফল্য। (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- তারাই তাদের রবের পক্ষ থেকে সৎপথে রয়েছে, আর তারাই সফলকাম। (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- তাকে এমন শাস্তি আসবে যা তাকে অপমানিত করবে এবং তার ওপর স্থায়ী শাস্তি নেমে আসবে। (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- তোমরা পৃথিবীতে ভ্রমণ কর এবং দেখ যে, মিথ্যারোপকারীদের পরিণতি কেমন ছিল। (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- তারা কখনই তা কামনা করবে না, কারণ তাদের হাত যা আগে পাঠিয়েছে, আর আল্লাহ জালিমদের জানেন। (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- তিনি ভালো জানেন কে তাঁর পথ থেকে পথভ্রষ্ট হয়েছে, এবং তিনি ভালো জানেন। (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- নিশ্চয় আল্লাহ আমার রব এবং তোমাদেরও রব; অতএব তোমরা তাঁর ইবাদত কর; এটাই সরল পথ। (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- মানুষের প্রতি অনুগ্রহশীল, কিন্তু তাদের অধিকাংশই কৃতজ্ঞতা প্রকাশ করে না। (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- আসমানসমূহ, যমীন এবং এ দুয়োর মধ্যে যা আছে, সবই সত্য ও নির্দিষ্ট মেয়াদের জন্য। (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- তাদেরকে ছেড়ে দাও, তারা বাজে কথায় ডুবে থাকুক ও খেলাধুলা করুক, যতক্ষণ না তারা তাদের সেই দিনের সম্মুখীন হয়, যে দিনের প্রতিশ্রুতি তাদের দেওয়া হয়েছে। (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- যখন তারা মুমিনদের সাথে সাক্ষাৎ করে, বলে: আমরা ঈমান এনেছি, আর যখন নির্জনে যায়। (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- তারা তাওরাত, ইঞ্জিল ও তাদের রবের পক্ষ থেকে যা কিছু নাযিল করা হয়েছে, তা প্রতিষ্ঠা করে। (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- তিনি জানেন তাদের সামনে কী আছে এবং তাদের পেছনে কী আছে, আর তারা তা জ্ঞানে পরিবেষ্টিত করতে পারে না। (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- তিনিই আসমানসমূহ ও যমীন ছয় দিনে সৃষ্টি করেছেন। (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- নিশ্চয় এতে তোমাদের জন্য নিদর্শন রয়েছে, যদি তোমরা মুমিন হও। (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- মানুষের কাছে পথনির্দেশ আসার পর, তাদের ঈমান আনায় কী বাধা দিল? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- তারা আল্লাহর শরীক স্থাপন করল, যাতে মানুষকে তাঁর পথ থেকে বিভ্রান্ত করে। বল: তোমরা উপভোগ কর। (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- তারা আশ্চর্য হলো যে, তাদের মধ্য থেকে একজন সতর্ককারী তাদের কাছে এল, আর কাফিররা বলল: এ। (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- নিশ্চয় তোমার রব ভালো জানেন কে তাঁর পথ থেকে পথভ্রষ্ট হয়েছে। (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- যে লোক দেখানোর জন্য নিজের সম্পদ ব্যয় করে এবং আল্লাহর প্রতি ঈমান আনে না। (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- আমি তোমাদের যে রিজিক দিয়েছি, তা থেকে সেই দিন আসার আগেই ব্যয় কর। (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- তিনি আসমানসমূহে ও যমীনে যা কিছু আছে, সবই তোমাদের অধীন করে দিয়েছেন। (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- আমরা তো সন্দেহে আছি যে, আপনি আমাদের যে দিকে ডাকছেন, সে বিষয়ে। (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- নিশ্চয় তোমার রব যার জন্য ইচ্ছা, রিজিক প্রশস্ত করেন এবং সংকুচিতও করেন। নিশ্চয় তিনি। (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- আসমানসমূহ ও যমীনের রব এবং এ দুয়োর মাঝে যা আছে, যদি তোমরা নিশ্চিত বিশ্বাসী হও। (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- আমরা আল্লাহর প্রতি ঈমান এনেছি এবং আমাদের প্রতি যা নাযিল হয়েছে এবং (পূর্ববর্তীদের) প্রতি যা নাযিল হয়েছে। (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- আর যারা জুলুম করেছিল, তাদেরকে ভয়াবহ শব্দ আক্রান্ত করল, ফলে তারা নিজেদের গৃহে উপুড় হয়ে পড়ে রইল। (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- সুতরাং তারা নিজেদের জন্য যা করে, তাতে তোমাদের কোনো অপরাধ নেই। (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- তোমার রব ভালো জানেন কে তাঁর পথ থেকে পথভ্রষ্ট হয়েছে, এবং তিনি। (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- তিনি তাঁর নির্দেশে নিজের বান্দাদের মধ্যে যাকে ইচ্ছা, রূহ (ওহী) প্রেরণ করেন। (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- আমি মারইয়াম-পুত্র ঈসাকে সুস্পষ্ট নিদর্শন দান করেছি এবং পবিত্র রূহ দ্বারা তাকে শক্তিশালী করেছি। (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- কিয়ামতের দিন তাদের মধ্যে সে বিষয়ে ফয়সালা করবেন, যে বিষয়ে তারা মতবিরোধ করত। (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- আমি তার উপরিভাগকে নিম্নভাগ করে দিয়েছি এবং তার উপর পোড়া মাটির পাথর বর্ষণ করেছি। (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- আপনি তাদেরকে সতর্ক করুন বা না করুন, তাদের জন্য সমান; তারা ঈমান আনবে না। (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- মানুষকে বাদ দিয়ে, যদি তোমরা সত্যবাদী হও, তবে মৃত্যু কামনা কর। (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- আল্লাহর (ইবাদত কর), তার বাইরে তোমাদের কোনো ইলাহ নেই। তবে কি তোমরা তাকওয়া অবলম্বন করবে না? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- আমি তাদেরকে যে প্রতিশ্রুতি দিচ্ছি, তার কিছু তোমাকে দেখালেও বা তোমাকে মৃত্যু দিলেও, শেষ পর্যন্ত আমাদের কাছেই তারা ফিরে আসবে। (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- তারা বলল: আমরা মৃত্যুবরণ করে মাটি ও হাড় হয়ে গেলেও, কি আমরা পুনরুত্থিত হব? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- অনুগ্রহ আল্লাহর হাতে, তিনি যাকে ইচ্ছা, তা দান করেন এবং আল্লাহ। (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- গায়েব ও প্রকাশ্য বিষয়ের জ্ঞানী আল্লাহর কাছে তোমরা ফিরে যাবে, তিনি তোমাদেরকে বলে দেবেন যা কিছু তোমরা করতে। (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- হে মুমিনগণ, তোমরা আল্লাহর সেই অনুগ্রহ স্মরণ কর, যখন। (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- আমি তোমার আগেও মানুষ ছাড়া কাউকে রাসূল করে পাঠাইনি, যাদের কাছে আমি ওহী প্রেরণ করতাম। (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- তিনি তার পাপ মোচন করবেন এবং তাকে জান্নাতে প্রবেশ করাবেন, যার নিচে নদী প্রবাহিত। (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- অসুস্থ বা সফররত অবস্থায়, তাহলে অন্য দিনগুলোতে (রোজা) পূর্ণ করবে। (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- তারা কেবল অনুমানের অনুসরণ করে এবং তারা কেবল মিথ্যা অনুমান করে। (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- যারা আল্লাহ ও শেষ দিনের আশা রাখে, তাদের জন্য উত্তম আদর্শ। (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- আমি আসমানসমূহ, যমীন এবং এগুলোর মাঝে যা আছে, তা সত্য ছাড়া সৃষ্টি করিনি। (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- তুমি তোমার হাত তোমার কোলের মধ্যে রাখ, তা কোনো রোগ ছাড়াই উজ্জ্বল হয়ে বের হবে। (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- তিনি নিজের রহমত দ্বারা যাকে ইচ্ছা, নির্বাচিত করেন এবং আল্লাহ মহা অনুগ্রহশীল। (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- তুমি কি জান না যে, আল্লাহর জন্য আসমানসমূহ ও যমীনের রাজত্ব? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- তোমরা নিজেদের জন্য যা কিছু উত্তম অগ্রিম পাঠাবে, তা আল্লাহর কাছে পাবে। (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- তুমি যেখান থেকেই বের হও, তোমার মুখ মাসজিদুল হারামের দিকে ফিরাও। (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- তাদের আগে যারা ছিল, তারা চলে গেছে; আল্লাহর বিধানে তুমি কোনো পরিবর্তন পাবে না। (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- যার জন্য আসমানসমূহে ও যমীনে যা কিছু আছে। (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- কোনো নারী গর্ভধারণ করে না এবং প্রসবও করে না, কিন্তু তাঁর জ্ঞান অনুযায়ী। (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- তিনি রাত, সূর্য ও চন্দ্রকে অধীন করেছেন; প্রত্যেকেই নির্দিষ্ট মেয়াদে চলছে। (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- যার নিচে নদী প্রবাহিত, সেখানে তারা চিরস্থায়ী হবে, এটাই প্রতিদান। (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- তিনি বললেন: বরং তোমাদের মন তোমাদের জন্য একটি বিষয় সুশোভিত করেছে; ধৈর্যই উত্তম। (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- আসমানসমূহে ও যমীনে যা কিছু আছে এবং নিশ্চয় আল্লাহ। (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- তাদের কাছে যে রাসূলই আসুক না কেন, তারা তাকে উপহাস করত। (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- তারা বলল: হে মূসা, হয় তুমি নিক্ষেপ কর, নয় আমরা নিক্ষেপ করি। (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- তিনিই তোমাদের মৃত্যু ঘটান এবং তোমাদের মধ্যে কাউকে সবচেয়ে নিকৃষ্ট বয়সে ফিরিয়ে দেওয়া হয়, যাতে। (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- তাদের রবের কাছে জান্নাত রয়েছে, যার নিচে নদী প্রবাহিত, সেখানে তারা চিরস্থায়ী হবে। (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- আমি তাদের অন্তরে আবরণ দিয়েছি, যাতে তারা তা না বোঝে, এবং তাদের কানে বধিরতা। (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- আল্লাহর প্রতিশ্রুতি সত্য, কিন্তু তাদের অধিকাংশই জানে না। (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- এটি এ কারণে যে, তারা আল্লাহ ও তাঁর রাসূলের বিরোধিতা করেছিল; আর যে আল্লাহর বিরোধিতা করে। (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- আর যেদিন তিনি তাদের ডাকবেন, বলবেন: আমার শরীকরা কোথায়, যাদের সম্পর্কে তোমরা ধারণা করতে? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- তারা কি দেখে না যে, আল্লাহই আসমানসমূহ ও যমীন সৃষ্টি করেছেন? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- যিনি তোমাকে মাটি থেকে, তারপর শুক্রাণু থেকে, তারপর। (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- তারা বলত: হে আমাদের রব, তুমি আমাদের কাছে রাসূল পাঠালে না কেন? তবে আমরা তোমার নিদর্শনসমূহ অনুসরণ করতাম। (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- তারপর তাদের রবের কাছে তাদের ফিরে যাওয়া; তিনি তাদেরকে জানিয়ে দেবেন যা তারা করত। (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- তাদের এ বিষয়ে কোনো জ্ঞান নেই; তারা কেবল অনুমান করে। (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- আমরা আমাদের পূর্বপুরুষদেরকে একটি মতের উপর পেয়েছি এবং আমরা তাদের পদাঙ্ক অনুসরণ করি। (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- যাদেরকে কিতাব দেওয়া হয়েছিল, তারা তাদের কাছে জ্ঞান আসার পরেই (মতভেদ করেছিল)। (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- যখন ইব্রাহীম বললেন: হে আমার রব, এই শহরকে নিরাপদ কর। (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- তিনি তোমাদের জন্য শ্রবণশক্তি, দৃষ্টিশক্তি ও অন্তর দিয়েছেন; তোমরা অল্পই কৃতজ্ঞতা প্রকাশ কর। (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- যারা কোনো প্রমাণ ছাড়াই আল্লাহর আয়াতসমূহ নিয়ে বিতর্ক করে। (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- তোমরা ইব্রাহীমের একনিষ্ঠ ধর্ম অনুসরণ কর, তিনি মুশরিকদের অন্তর্ভুক্ত ছিলেন না। (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- স্মরণ কর, যখন আমি তোমাদেরকে ফিরআউনের বংশধরদের থেকে উদ্ধার করেছিলাম, যারা তোমাদেরকে নিকৃষ্টতম শাস্তি দিত। (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- এটাই সঠিক দ্বীন, কিন্তু অধিকাংশ মানুষ জানে না। (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- তুমি কি দেখ না যে, আল্লাহ তোমাদের জন্য যা কিছু আছে, তা তোমাদের অধীন করে দিয়েছেন? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- যারা কুফরী করে, তারা বলত: এটি স্পষ্ট জাদু ছাড়া কিছুই নয়। (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- যখন তাদের কাছে আমার স্পষ্ট আয়াতসমূহ তিলাওয়াত করা হয়, তখন কাফিররা বলে। (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- স্থায়ী জান্নাত, যার নিচে নদী প্রবাহিত, সেখানে তারা চিরস্থায়ী হবে। (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- তিনি যা ইচ্ছা করেন, আল্লাহ সবকিছুর উপর ক্ষমতাবান। (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- যাতে তিনি তোমাদের পাপ মোচন করেন এবং তোমাদেরকে নির্দিষ্ট সময় পর্যন্ত অবকাশ দেন। (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- তোমরা কি আমাদেরকে আমাদের পূর্বপুরুষরা যার ইবাদত করত, তা থেকে ফিরিয়ে দিতে চাও? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- যখন তোমার রব ফেরেশতাদের বললেন: আমি মাটি থেকে মানুষ সৃষ্টি করছি। (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- তিনিই বাতাস প্রেরণ করেন, যা তাঁর রহমতের আগে সুসংবাদ দেয়। (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- বল: পৃথিবীতে ভ্রমণ কর এবং দেখ যে পরিণতি কেমন ছিল। (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- আসমানসমূহ ও যমীনের সৃষ্টিতে এবং রাত ও দিনের পরিবর্তনে (নিদর্শন রয়েছে)। (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- কে সেই ব্যক্তি, যে আল্লাহকে উত্তম ঋণ দেবে, যাতে তিনি তা বহুগুণে বৃদ্ধি করেন? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- অতএব, তাদের মধ্যে আল্লাহ যা নাযিল করেছেন, তা অনুযায়ী বিচার কর এবং তাদের খেয়াল-খুশির অনুসরণ করো না। (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- তারা কি এই অপেক্ষা করে যে, তাদের কাছে ফেরেশতারা আসবে, অথবা তোমার রবের আদেশ আসবে? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- যারা আল্লাহর উপর মিথ্যা রচনা করে, তারা কখনই সফল হবে না। (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- ফিরআউনের বংশধরদের এবং তাদের পূর্ববর্তীদের অবস্থার মতো, তারা আমার আয়াতসমূহকে মিথ্যা বলেছে। (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- তিনি মুমিনদের সুসংবাদ দেন যারা সৎকর্ম করে, যে তাদের জন্য রয়েছে উত্তম প্রতিদান। (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- আল্লাহ যাকে ইচ্ছা, তার বান্দাদের মধ্যে রিজিক প্রশস্ত করেন এবং সংকুচিতও করেন। (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- তোমরা গায়েব ও প্রকাশ্য বিষয়ের জ্ঞানীর কাছে ফিরে যাবে, তিনি তোমাদেরকে বলে দেবেন যা তোমরা করতে। (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- আর আত্মীয়-স্বজনরা আল্লাহর কিতাবে একে অপরের বেশি ঘনিষ্ঠ। (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
